import React, { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { setView } from '../../actions'
import './Filter.css'

export const Filter = (props) => {

    const { recipesIn, setView, diets } = props

    const [newRecipesOut, setNewRecipesOut] = useState(recipesIn)

    useEffect(()=>{
        if(newRecipesOut.length ) setView(newRecipesOut);
        else setView(recipesIn)
    }, [recipesIn, newRecipesOut])


    function filter(e) {
        e.preventDefault();
        const { target } = e;
        const { value } = target;
        let newToShow = recipesIn
        if (value) newToShow = newToShow.filter(r => r.diets.includes(value));
        setNewRecipesOut(newToShow);
    }

    function reset(e) {
        e.preventDefault();
        setNewRecipesOut(recipesIn);
    }


    function order(e) {
        e.preventDefault();
        const { target } = e;
        const { value } = target;
        let newToShow = recipesIn
        if (value === 'A-Z') newToShow = [ ...newToShow ].sort((a, b) => a.title > b.title ? 1 : -1);
        else if (value === 'Z-A') newToShow = [ ...newToShow ].sort((a, b) => a.title < b.title ? 1 : -1);
        else if (value === 'Most Likes') newToShow = [ ...newToShow ].sort((a, b) => (b.aggregateLikes - a.aggregateLikes));
        else if (value === 'Health Score') newToShow = [ ...newToShow ].sort((a, b) => (b.healthScore - a.healthScore));
        setNewRecipesOut(newToShow);
    }

    return (
        <div key='filter' className='filter'>
            <b>Filter :</b>
            {diets.map((d, i) =>
                <input key={i} type='button' value={d.diet} onClick={filter} />)}
            <b>Sort By :</b>
            <input key='Alphabetic' type='button' value='A-Z' onClick={order} />
            <input key='revAlphabetic' type='button' value='Z-A' onClick={order} />
            <input key='likes' type='button' value='Most Likes' onClick={order} />
            <input key='health' type='button' value='Health Score' onClick={order} />
            <input key='reset' type='button' value='Reset' onClick={reset} />
        </div>
    )
}


const mapStateToProps = (state) => {
    return {
        diets: state.diets,
        recipesIn: state.recipesIn
    }
}

const mapDispatchToProps = (dispatch) => {
    return {
        setView: (toShow) => dispatch(setView(toShow))
    }
}


export default connect(mapStateToProps, mapDispatchToProps)(Filter)



